INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('reading', '{"text": "Photography has become much easier since the invention of digital cameras and smartphones. In the past, people had to buy rolls of film and wait days to see their pictures developed. Now, photos can be viewed, edited, and shared instantly. Despite these changes, many photographers still value the careful planning that traditional photography required."}'::jsonb, '{"exact": "Photography has become much easier since the invention of digital cameras and smartphones. In the past, people had to buy rolls of film and wait days to see their pictures developed. Now, photos can be viewed, edited, and shared instantly. Despite these changes, many photographers still value the careful planning that traditional photography required."}'::jsonb, 56, 0.40, 'B1', 'approved', 'exam', 'culture', 'b5000000-0000-4000-8000-000000000011', 1),
('reading', '{"text": "Street performers can be found in cities all over the world. They often play music, perform magic tricks, or act out short plays for passersby. Many street performers rely on small donations from their audience to earn a living. Some have even become famous after being discovered while performing in a public square."}'::jsonb, '{"exact": "Street performers can be found in cities all over the world. They often play music, perform magic tricks, or act out short plays for passersby. Many street performers rely on small donations from their audience to earn a living. Some have even become famous after being discovered while performing in a public square."}'::jsonb, 54, 0.43, 'B1', 'approved', 'exam', 'culture', 'b5000000-0000-4000-8000-000000000011', 2);
