INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Learning to play a musical instrument offers benefits that go well beyond simply making music. Studies suggest that regular practice can improve memory, concentration, and coordination, particularly when learners start at a young age. Many people also find that playing an instrument helps reduce stress after a long day. Although progress can feel slow at first, consistent short practice sessions tend to work better than occasional long ones. Group lessons or playing with others can add a valuable social element as well. Whatever instrument someone chooses, patience and regular practice remain the most important ingredients for improvement."}'::jsonb, '{"exact": "Learning to play a musical instrument offers benefits that go well beyond simply making music. Studies suggest that regular practice can improve memory, concentration, and coordination, particularly when learners start at a young age. Many people also find that playing an instrument helps reduce stress after a long day. Although progress can feel slow at first, consistent short practice sessions tend to work better than occasional long ones. Group lessons or playing with others can add a valuable social element as well. Whatever instrument someone chooses, patience and regular practice remain the most important ingredients for improvement."}'::jsonb, 96, 0.47, 'B1', 'approved', 'exam', 'culture', 'b5000000-0000-4000-8000-000000000015', 1);
