INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Yuki had been practicing violin for a big recital for months. On the night of the show, she felt extremely nervous backstage. Once she started playing, her nerves disappeared completely. The audience applauded loudly, and Yuki felt proud of her performance."}'::jsonb, '{"key_points": ["Yuki practiced for months", "she felt nervous backstage", "her nerves disappeared once she started playing", "the audience applauded and she felt proud"]}'::jsonb, 40, 0.50, 'B1', 'approved', 'exam', 'culture', 'b5000000-0000-4000-8000-000000000018', 1),
('passage_reconstruction', '{"passage": "A street artist began painting a large mural on an empty wall downtown. At first, only a few curious people stopped to watch him work. By the final day, a large crowd had gathered to admire the finished piece together, and local newspapers even wrote a short story about it."}'::jsonb, '{"key_points": ["a street artist painted a mural downtown", "few people watched at first", "a large crowd gathered by the final day", "newspapers wrote about it"]}'::jsonb, 47, 0.53, 'B2', 'approved', 'exam', 'culture', 'b5000000-0000-4000-8000-000000000018', 2),
('passage_reconstruction', '{"passage": "A small theater group decided to perform a play entirely outdoors. Rain threatened the first show, but the weather cleared just in time. The audience loved the unusual setting, and the group decided to make outdoor shows a yearly tradition."}'::jsonb, '{"key_points": ["a theater group performed outdoors", "rain threatened but cleared in time", "the audience loved the setting", "they made it a yearly tradition"]}'::jsonb, 40, 0.55, 'B2', 'approved', 'exam', 'culture', 'b5000000-0000-4000-8000-000000000018', 3);
INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('summary_and_opinion', '{"passage": "Many schools around the world include art and music classes as part of their regular curriculum, while others treat these subjects as optional extras. This has led to an ongoing debate about whether art and music education should be mandatory for all students, regardless of their main academic interests.\n\nSupporters of mandatory arts education argue that these subjects help develop creativity, emotional expression, and problem-solving skills that are not always addressed in subjects like mathematics or science. They point out that learning to play an instrument or create visual art can improve concentration and discipline, skills that often transfer to other areas of learning. Additionally, exposure to the arts can help students discover talents and interests they might not encounter otherwise.\n\nOn the other hand, some educators argue that school time and resources are limited, and subjects like reading, mathematics, and science should remain the top priority. They suggest that art and music could instead be offered as voluntary after-school activities for students who are genuinely interested, rather than a requirement for everyone. Critics also note that forcing students who have little interest in the arts to participate may not be an effective use of class time.\n\nOverall, both sides raise valid concerns about how schools should balance academic priorities with creative development. Whether art and music become mandatory likely depends on each school''s resources, goals, and the broader educational philosophy it chooses to follow, as well as the needs of its particular student population."}'::jsonb, '{"key_points": ["schools debate whether arts education should be mandatory", "supporters say it builds creativity and transferable skills", "critics say core subjects should stay the priority", "the answer depends on each school''s resources and goals"]}'::jsonb, 276, 0.60, 'B2', 'approved', 'exam', 'education', 'b5000000-0000-4000-8000-000000000019', 1);
